// Remembers the last commit it saw (n8n saves this between runs of the ACTIVE workflow).
// First run: just remember the current commit. Later runs: continue only when a new commit arrived.
const data = $getWorkflowStaticData('global');
const c = $input.first().json;
const settings = $('Settings').first().json;
if (!c.sha) throw new Error('GitHub did not return a commit: ' + JSON.stringify(c).slice(0, 200));
data.repoName = `${settings.owner}/${settings.repo}`;
if (!data.lastSha) { data.lastSha = c.sha; return []; }
if (data.lastSha === c.sha) return [];
data.lastSha = c.sha;
const message = c.commit.message || '';
if (message.includes('[skip changelog]')) return [];
return [{ json: {
  ...settings,
  sha: c.sha,
  shortSha: c.sha.slice(0, 7),
  message,
  author: (c.commit.author || {}).name || '',
  date: (c.commit.author || {}).date || '',
  url: c.html_url,
  files: (c.files || []).map(f => ({ name: f.filename, status: f.status, additions: f.additions, deletions: f.deletions })),
} }];

// Turns the commit into release notes and adds them to the changelog n8n keeps (newest first, last 20).
const data = $getWorkflowStaticData('global');
const c = $input.first().json;
const [title, ...rest] = c.message.split('\n');
const entry = {
  title,
  details: rest.join('\n').trim(),
  date: c.date,
  commit: c.shortSha,
  url: c.url,
  author: c.author,
  files: c.files,
  publishedAt: new Date().toISOString(),
};
data.changelog = [entry, ...(data.changelog || [])].slice(0, 20);
return [{ json: entry }];

// Builds the public changelog page from what n8n saved. Anyone with the link can read it, no login.
const data = $getWorkflowStaticData('global');
const esc = t => String(t ?? '').replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const items = (data.changelog || []).map(e => `
  <article>
    <h2>${esc(e.title)}</h2>
    <p class="meta">${esc(e.date.slice(0, 16).replace('T', ' '))} UTC &middot; commit <a href="${esc(e.url)}">${esc(e.commit)}</a> &middot; ${esc(e.author)}</p>
    ${e.details ? `<p>${esc(e.details)}</p>` : ''}
    <ul>${e.files.map(f => `<li><code>${esc(f.name)}</code> ${esc(f.status)} <span class="add">+${f.additions}</span> <span class="del">-${f.deletions}</span></li>`).join('')}</ul>
  </article>`).join('') || '<p class="meta">No changes yet. Push a commit and this page updates by itself.</p>';
const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Changelog - ${esc(data.repoName)}</title>
<style>
:root{--ink:#111111;--graphite:#262626;--bone:#F3EFE7;--gray:#A7A29A;--lime:#B7F34A}
body{margin:0;background:var(--ink);color:var(--bone);font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif;display:flex;justify-content:center;padding:40px 16px}
main{width:100%;max-width:640px}h1{font-size:28px;margin:0 0 4px}.meta{color:var(--gray);font-size:14px}
article{background:var(--graphite);border-radius:12px;padding:18px 20px;margin-top:16px}h2{font-size:20px;margin:0 0 6px}
a{color:var(--bone)}code{font-family:"JetBrains Mono",ui-monospace,monospace;font-size:13px}ul{padding-left:18px;margin:10px 0 0}
.add{color:var(--lime)}.del{color:var(--gray)}
</style></head><body><main><h1>Changelog</h1>
<p class="meta">${esc(data.repoName)} &middot; updated automatically by n8n for every new commit</p>${items}</main></body></html>`;
return [{ json: { html } }];
